<style>
.compare-page{max-width:1120px;margin:32px auto 56px;padding:0 16px}.compare-hero,.compare-card{background:#fff;border:1px solid #e0e7f0;border-radius:16px;box-shadow:0 4px 18px #13294b0a}.compare-hero{padding:28px;margin-bottom:22px}.compare-hero h1{font-size:30px;font-weight:750;margin:0 0 8px}.compare-hero p{color:#65748b;margin:0}.compare-card{padding:24px;margin-bottom:22px}.compare-card h2{font-size:21px;font-weight:700;margin:0 0 18px}.pick-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pick{position:relative}.pick label{font-weight:600;display:block;margin-bottom:7px}.pick input,.advisor textarea{width:100%;padding:12px 14px;border:1px solid #d7e0ec;border-radius:10px;font:inherit}.suggestions{position:absolute;z-index:10;left:0;right:0;top:74px;background:white;border:1px solid #dae2ed;border-radius:10px;box-shadow:0 8px 24px #0002;max-height:320px;overflow:auto}.suggestion{width:100%;display:flex;align-items:center;gap:12px;padding:9px 12px;border:0;background:#fff;text-align:left}.suggestion:hover{background:#f2f7ff}.suggestion img,.picked img{width:54px;height:54px;object-fit:contain;border-radius:8px;background:#f7f8fa}.suggestion span{display:grid}.picked{display:flex;align-items:center;gap:12px;padding:12px;margin-top:10px;border:1px solid #e3e9f1;border-radius:10px;min-height:80px}.picked a{margin-left:auto}.compare-actions{margin-top:20px}.btn-compare{background:#1769ff;color:#fff;border:0;border-radius:9px;padding:11px 20px;font-weight:650}.btn-compare:disabled{opacity:.55}.compare-table{width:100%;border-collapse:collapse}.compare-table th,.compare-table td{padding:13px;border-bottom:1px solid #e6ebf2;text-align:left;vertical-align:top}.compare-table th{background:#f5f8fc}.compare-table td:first-child{font-weight:650;width:24%}.advisor textarea{min-height:115px;resize:vertical}.advisor-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px;flex-wrap:wrap}.advisor-hint,.compare-status{color:#68768a;font-size:14px;margin-top:10px}.ai-answer{white-space:pre-wrap;line-height:1.7;margin-top:18px}.sources{margin-top:14px;padding-left:22px}.sources li{margin:6px 0}.hidden{display:none!important}@media(max-width:700px){.pick-grid{grid-template-columns:1fr}.compare-card{padding:17px}.compare-table th,.compare-table td{padding:9px;font-size:14px}.compare-table td:first-child{width:28%}}
</style>
<main class="compare-page">
    <section class="compare-hero"><h1>So sánh điện thoại</h1><p>Chọn hai sản phẩm để đối chiếu giá và thông số thực tế tại cửa hàng, sau đó hỏi AI theo nhu cầu của bạn.</p></section>
    <section class="compare-card" aria-labelledby="compare-title">
        <h2 id="compare-title">Chọn sản phẩm</h2>
        <div class="pick-grid">
            <div class="pick"><label for="search-a">Điện thoại thứ nhất</label><input id="search-a" type="search" autocomplete="off" placeholder="Nhập tên điện thoại..."><div id="suggest-a" class="suggestions hidden"></div><div id="picked-a" class="picked">Chưa chọn sản phẩm</div></div>
            <div class="pick"><label for="search-b">Điện thoại thứ hai</label><input id="search-b" type="search" autocomplete="off" placeholder="Nhập tên điện thoại..."><div id="suggest-b" class="suggestions hidden"></div><div id="picked-b" class="picked">Chưa chọn sản phẩm</div></div>
        </div>
        <div class="compare-actions"><button id="compare-button" class="btn-compare" disabled>So sánh ngay</button><span id="compare-status" class="compare-status" role="status"></span></div>
    </section>
    <section id="comparison" class="compare-card hidden"><h2>Kết quả so sánh</h2><div id="table-wrap"></div><div id="comparison-links" class="pick-grid" style="margin-top:16px"></div></section>
    <section class="compare-card advisor"><h2>Tư vấn theo nhu cầu</h2><label for="question">Bạn cần máy trong tầm giá nào, dùng chủ yếu để làm gì?</label><textarea id="question" maxlength="1000" placeholder="Ví dụ: ngân sách khoảng 20 triệu, ưu tiên pin lâu và chụp ảnh..."></textarea><div class="advisor-tools"><span class="advisor-hint">Chế độ miễn phí: AI phân tích dữ liệu cửa hàng, không tìm kiếm web.</span><button id="ask-button" class="btn-compare">Nhận tư vấn AI</button></div><div id="ai-status" class="compare-status" role="status"></div><div id="ai-answer" class="ai-answer hidden"></div><div id="source-wrap" class="hidden"><h3>Nguồn tham khảo</h3><p id="no-sources" class="advisor-hint hidden">Không có nguồn web được xác minh trong lần truy vấn này.</p><ul id="source-list" class="sources"></ul></div></section>
</main>
<script>
(() => {
 const base=<?= json_encode(rtrim(url('compare'), '/'), JSON_UNESCAPED_SLASHES) ?>;
 const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';
 const selected=[null,null], timers=[null,null];
 const escUrl=value=>{try{const u=new URL(value,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
 const formBody=values=>new URLSearchParams({...values,csrf_token:csrf});
 const post=async(path,values)=>{const r=await fetch(base+'/'+path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:formBody(values)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Không thể xử lý yêu cầu.');return j};
 const updateButton=()=>document.getElementById('compare-button').disabled=!(selected[0]&&selected[1]&&selected[0].id!==selected[1].id);
 function showPicked(i,p){selected[i]=p;const box=document.getElementById(i?'picked-b':'picked-a');box.replaceChildren();if(!p){box.textContent='Chưa chọn sản phẩm';updateButton();return}const img=document.createElement('img');img.src=p.image;img.alt='';const title=document.createElement('strong');title.textContent=p.name;const price=document.createElement('span');price.textContent=p.price_formatted;const link=document.createElement('a');link.href=escUrl(p.url);link.textContent='Chi tiết';link.rel='noopener';box.append(img,title,price,link);document.getElementById(i?'suggest-b':'suggest-a').classList.add('hidden');updateButton()}
 function showSuggestions(i,items){const box=document.getElementById(i?'suggest-b':'suggest-a');box.replaceChildren();if(!items.length){box.classList.add('hidden');return}items.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='suggestion';const im=document.createElement('img');im.src=p.image;im.alt='';const txt=document.createElement('span');const name=document.createElement('strong');name.textContent=p.name;const price=document.createElement('small');price.textContent=p.price_formatted;txt.append(name,price);b.append(im,txt);b.addEventListener('click',()=>showPicked(i,p));box.append(b)});box.classList.remove('hidden')}
 [0,1].forEach(i=>document.getElementById(i?'search-b':'search-a').addEventListener('input',e=>{clearTimeout(timers[i]);const q=e.target.value.trim();if(q.length<2){showSuggestions(i,[]);return}timers[i]=setTimeout(async()=>{try{const r=await fetch(base+'/products?q='+encodeURIComponent(q));const j=await r.json();showSuggestions(i,j.products||[])}catch{showSuggestions(i,[])}},250)}));
 document.addEventListener('click',e=>{if(!e.target.closest('.pick'))document.querySelectorAll('.suggestions').forEach(x=>x.classList.add('hidden'))});
 const ids=()=>selected.filter(Boolean).map(p=>String(p.id));
 document.getElementById('compare-button').addEventListener('click',async()=>{const status=document.getElementById('compare-status'),button=document.getElementById('compare-button');status.textContent='Đang tải dữ liệu...';button.disabled=true;try{const j=await post('compare',{product_ids:ids().join(',')});renderComparison(j.products);status.textContent='';}catch(e){status.textContent=e.message}finally{updateButton()}});
 function renderComparison(products){const names=new Set();products.forEach(p=>p.specs.forEach(s=>names.add(s.name)));const rows=[['Giá bán tại cửa hàng',p=>p.price_formatted]];[...names].forEach(n=>rows.push([n,p=>p.specs.find(s=>s.name===n)?.value||'Chưa có thông tin']));const table=document.createElement('table');table.className='compare-table';const head=document.createElement('tr');['Tiêu chí',...products.map(p=>p.name)].forEach(t=>{const th=document.createElement('th');th.textContent=t;head.append(th)});const thead=document.createElement('thead');thead.append(head);const body=document.createElement('tbody');rows.forEach(([label,get])=>{const tr=document.createElement('tr');const th=document.createElement('td');th.textContent=label;tr.append(th);products.forEach(p=>{const td=document.createElement('td');td.textContent=get(p);tr.append(td)});body.append(tr)});table.append(thead,body);document.getElementById('table-wrap').replaceChildren(table);const links=document.getElementById('comparison-links');links.replaceChildren();products.forEach(p=>{const a=document.createElement('a');a.href=escUrl(p.url);a.textContent='Xem '+p.name;a.rel='noopener';links.append(a)});document.getElementById('comparison').classList.remove('hidden')}
 document.getElementById('ask-button').addEventListener('click',async e=>{const button=e.currentTarget,status=document.getElementById('ai-status'),answer=document.getElementById('ai-answer'),wrap=document.getElementById('source-wrap'),list=document.getElementById('source-list');const question=document.getElementById('question').value.trim();if(!question){status.textContent='Hãy nhập nhu cầu để được tư vấn.';return}button.disabled=true;status.textContent='AI đang phân tích...';answer.classList.add('hidden');wrap.classList.add('hidden');try{const j=await post('advice',{question,product_ids:ids().join(',')});answer.textContent=j.answer;answer.classList.remove('hidden');list.replaceChildren();(j.sources||[]).forEach(s=>{const li=document.createElement('li'),a=document.createElement('a');a.href=escUrl(s.url);a.target='_blank';a.rel='noopener noreferrer';a.textContent=s.title||s.url;li.append(a);list.append(li)});document.getElementById('no-sources').classList.toggle('hidden',!!(j.sources||[]).length);wrap.classList.remove('hidden');status.textContent=j.web_available===false?'Chế độ miễn phí dùng dữ liệu cửa hàng, không tìm kiếm web.':''}catch(err){status.textContent=err.message}finally{button.disabled=false}});
})();
</script>
